class ApiError extends Error {
  constructor(status, code, title, extra = {}) { super(title); Object.assign(this, { status, code, extra }) }
}

app.use((err, req, res, next) => {
  const known = err instanceof ApiError
  if (!known) log.error({ err, requestId: req.id })
  res.status(known ? err.status : 500).type('application/problem+json').json({
    type: known ? `https://api.example.com/problems/${err.code}` : 'about:blank',
    title: known ? err.message : 'Internal error',
    status: known ? err.status : 500,
    code: known ? err.code : 'internal',
    request_id: req.id,
    ...(known ? err.extra : {}),
  })
})

